// QUALITY: 78/100 — generated data twin: proven byte-fidelity (ε0 full-value), embedded blob unreadable by design
use serde_json::Value;
use std::sync::LazyLock;

pub static ACTIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"name":"system.memory.list","description":"Query memories with filters (type, tag, source_card, validated, minConfidence, activeOnly, limit).","owner_agent":"system","steps_json":"[{\"skill\":\"memory-list\",\"input\":\"$.input\",\"as\":\"memories\"}]","returns":"$.results.memories","on_failure":"abort"},{"name":"system.memory.log","description":"Render memories as a colored text feed grouped by type.","owner_agent":"system","steps_json":"[{\"skill\":\"memory-log\",\"input\":\"$.input\",\"as\":\"log\"}]","returns":"$.results.log","on_failure":"abort"},{"name":"system.memory.html","description":"Render memories as a single HTML page, grouped by type with anchor links.","owner_agent":"system","steps_json":"[{\"skill\":\"memory-html\",\"input\":\"$.input\",\"as\":\"html\"}]","returns":"$.results.html","on_failure":"abort"},{"name":"system.memory.export.training","description":"Emit JSONL training data from validated memories. Formats: sft (default), preference (DPO pairs), tagged (debug).","owner_agent":"system","steps_json":"[{\"skill\":\"memory-export-training\",\"input\":\"$.input\",\"as\":\"export\"}]","returns":"$.results.export","on_failure":"abort"},{"name":"system.memory.similar","description":"Cosine-similarity search over stored embeddings. Caller provides query vector + model + optional filters (embedded_field, limit, minScore).","owner_agent":"system","steps_json":"[{\"skill\":\"memory-similar\",\"input\":\"$.input\",\"as\":\"results\"}]","returns":"$.results.results","on_failure":"abort"},{"name":"system.memory.graph","description":"BFS the memory_links graph from a seed memory. Returns {nodes, edges}.","owner_agent":"system","steps_json":"[{\"skill\":\"memory-graph\",\"input\":\"$.input\",\"as\":\"graph\"}]","returns":"$.results.graph","on_failure":"abort"},{"name":"system.memory.rag.context","description":"GraphRAG retrieval from a query: embeds { query } locally, then combines vector similarity + graph expansion. Returns top-N memories ranked by composite score (similarity + graph proximity + confidence). Pass a precomputed { vector } to skip embedding.","owner_agent":"system","steps_json":"[{\"skill\":\"memory-rag-query\",\"input\":\"$.input\",\"as\":\"context\"}]","returns":"$.results.context","on_failure":"abort"},{"name":"system.memory.graph.html","description":"Render the memory graph as an interactive HTML+SVG page. Pass seed_memory_id for concentric layout, omit for whole-graph grid layout.","owner_agent":"system","steps_json":"[{\"skill\":\"memory-graph-html\",\"input\":\"$.input\",\"as\":\"html\"}]","returns":"$.results.html","on_failure":"abort"},{"name":"system.memory.use.list","description":"Query memory_uses with optional filters + LATEST outcome rating per use. Filters: memory_id, used_by, context_card, context_session, since, ratedOnly, outcome, limit.","owner_agent":"system","steps_json":"[{\"skill\":\"memory-use-list\",\"input\":\"$.input\",\"as\":\"uses\"}]","returns":"$.results.uses","on_failure":"abort"}]"#).expect("ACTIONS: embedded JSON is valid by construction")
});

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn actions_parses_with_the_pressed_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 9, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

}
